  public getUVs(blockId: BlockType): BlockUVs {
    const uvs = this.uvMap.get(blockId);
    if (!uvs) {
      // Fallback to stone
      return this.uvMap.get(BlockType.STONE)!;
    }
    return uvs;
  }

  /**
   * Advances the animated water texture across its smooth fluid loop.
   * Modifies the atlas canvas tile directly and triggers GPU texture upload.
   */
  public updateWater(delta: number): boolean {
    const totalFrames = this.waterFrames.length;
    if (totalFrames < 2 || this.waterTiles.length === 0) return false;
    this.waterAnimTimer += delta;
    const FRAME_DURATION = 0.30; // ~3.3 fps calm, soothing fluid wave progression
    if (this.waterAnimTimer >= FRAME_DURATION) {
      this.waterAnimTimer %= FRAME_DURATION;
      this.currentWaterFrame = (this.currentWaterFrame + 1) % totalFrames;
      const frameData = this.waterFrames[this.currentWaterFrame];
      for (const tile of this.waterTiles) {
        this.ctx.putImageData(frameData, tile.col * TILE_SIZE, tile.row * TILE_SIZE);
      }
      this.texture.needsUpdate = true;
      return true;
    }
    return false;
  }

  public dispose() {
    // Clean up Three.js texture resources
    if (this.texture) {
      this.texture.dispose();
    }
    // Clear UV map to free memory
    this.uvMap.clear();
    this.waterFrames = [];
    this.waterTiles = [];
  }
